 if(argc!=2)return 2;const auto dir=std::filesystem::path(argv[1]);std::filesystem::create_directories(dir);Mesh mesh;mesh.positions={{-.3f,-.2f,0},{.3f,-.2f,0},{.3f,.2f,0},{-.3f,.2f,0}};mesh.normals.assign(4,{0,0,1});mesh.uv={{0,0},{1,0},{1,1},{0,1}};mesh.indices={0,1,2,0,2,3};Scene scene;auto id=scene.add("Actual generated rigged quad",Volume{});auto&o=scene.object(id);o.painted=std::make_shared<PaintedMesh>(mesh,64);o.mesh_active=true;Skeleton skeleton;Bone root;root.name="Authored root";root.length=.137f;Bone child;child.name="Authored second joint";child.parent=0;child.rest.translation={0,.1f,0};child.length=.237f;skeleton.bones={root,child};DeformationState d(mesh);d.skeleton=skeleton;d.skin=SkinWeights{};d.skin->vertices.assign(4,{{0,.5f},{1,.5f}});o.deformation=std::make_shared<const DeformationState>(d);o.affine_edit=std::make_shared<const NativeAffineEdit>(AffineTransform(std::array<double,16>{-1,0,0,0,.2,.9,0,0,.1,.05,1.1,0,.03,-.02,.01,1}));scene.validate();const auto path=dir/"generated.glb";export_glb(scene.surfaces(),path);ImportAuthoringOptions options;options.paint_resolution=64;auto adopted=prepare_authoring_import(Scene{},path,options);check(adopted.objects.size()==1,"Actual generic GLB freshly adopts the authored skinned mesh");auto selected=adopted.objects.front();const auto &a=*adopted.scene.object(selected).appearance;auto metadata=detail::source_bone_metadata(*a.asset);size_t authored=0;uint32_t second=UINT32_MAX;for(size_t slot=0;slot<a.source_joint_nodes.size();++slot){auto source=a.source_joint_nodes[slot];if(!metadata.lengths[source])continue;const auto l=adopted.scene.object(selected).deformation->skeleton->bones[slot].length;check(l==*metadata.lengths[source],"Generic GLB restores exact actual-source localY length into its own native slot");if(l==.237f)second=uint32_t(slot);++authored;}check(authored==2&&second!=UINT32_MAX,"Both genuine generated joint lengths survive generic native reimport");const auto original=adopted.scene.encode();